CREATE TABLE IF NOT EXISTS "ai_scenarios" (
	"key" text PRIMARY KEY NOT NULL,
	"emoji" text NOT NULL,
	"sort_order" integer DEFAULT 0 NOT NULL,
	"active" boolean DEFAULT true NOT NULL,
	"title" jsonb NOT NULL,
	"description" jsonb NOT NULL,
	"role" text NOT NULL,
	"scene" text NOT NULL,
	"openings" jsonb NOT NULL,
	"scene_svg" text,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
-- Seed: hand-written scenes (no tokens spent to start a conversation).
INSERT INTO "ai_scenarios" ("key","emoji","sort_order","title","description","role","scene","openings","scene_svg") VALUES ('store','🛍️',1,'{"en": "At the store", "es": "En la tienda"}'::jsonb,'{"en": "Buy clothes, ask about sizes and prices.", "es": "Compra ropa, pregunta tallas y precios."}'::jsonb,'a friendly shop assistant','a small clothing store; the learner is a customer','{"spanish": "¡Hola, bienvenido a la tienda! ¿Buscas algo en especial hoy?", "english": "Hi, welcome to the store! Are you looking for anything special today?"}'::jsonb,'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240"><rect width="400" height="240" fill="#fdeee8"/><rect y="190" width="400" height="50" fill="#f3d6c8"/><rect x="30" y="40" width="200" height="12" rx="4" fill="#f08a6c"/><line x1="40" y1="52" x2="40" y2="70" stroke="#b7795f" stroke-width="3"/><line x1="220" y1="52" x2="220" y2="70" stroke="#b7795f" stroke-width="3"/><path d="M48 70h36l-6 60H54z" fill="#7cc4b4"/><path d="M98 70h36l-6 60h-24z" fill="#f7c873"/><path d="M148 70h36l-6 60h-24z" fill="#9db8e8"/><path d="M198 70h28l-4 60h-20z" fill="#f2a1b8"/><rect x="250" y="120" width="120" height="70" rx="6" fill="#c98e6c"/><rect x="262" y="104" width="30" height="16" rx="3" fill="#7d8aa6"/><circle cx="330" cy="78" r="18" fill="#e9b89a"/><path d="M312 72a18 18 0 0 1 36 0z" fill="#5b3a2e"/><rect x="314" y="96" width="32" height="26" rx="8" fill="#f08a6c"/><circle cx="80" cy="150" r="16" fill="#d9a07f"/><path d="M64 146a16 16 0 0 1 32 0z" fill="#2f2a28"/><rect x="66" y="166" width="28" height="26" rx="8" fill="#5f9ed1"/><rect x="96" y="168" width="18" height="20" rx="3" fill="#f7c873"/></svg>') ON CONFLICT ("key") DO NOTHING;--> statement-breakpoint
INSERT INTO "ai_scenarios" ("key","emoji","sort_order","title","description","role","scene","openings","scene_svg") VALUES ('restaurant','🍽️',2,'{"en": "At the restaurant", "es": "En el restaurante"}'::jsonb,'{"en": "Order food and ask for the bill.", "es": "Pide la comida y la cuenta."}'::jsonb,'a waiter','a cozy restaurant; the learner is ordering a meal','{"spanish": "¡Buenas tardes! Aquí tiene el menú. ¿Qué le gustaría tomar?", "english": "Good afternoon! Here is the menu. What would you like to drink?"}'::jsonb,'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240"><rect width="400" height="240" fill="#fff4e6"/><rect y="195" width="400" height="45" fill="#e8cfb0"/><rect x="40" y="30" width="90" height="60" rx="6" fill="#bfe3f2"/><line x1="85" y1="30" x2="85" y2="90" stroke="#fff" stroke-width="4"/><circle cx="300" cy="50" r="22" fill="#f7c873"/><rect x="120" y="140" width="170" height="10" rx="4" fill="#c98e6c"/><rect x="135" y="150" width="8" height="45" fill="#a46f52"/><rect x="267" y="150" width="8" height="45" fill="#a46f52"/><path d="M110 132h190v8H110z" fill="#f08a6c"/><ellipse cx="170" cy="128" rx="20" ry="6" fill="#fff"/><circle cx="170" cy="124" r="7" fill="#e86f4f"/><rect x="230" y="110" width="8" height="20" rx="2" fill="#9ad0c2"/><circle cx="90" cy="120" r="16" fill="#e9b89a"/><path d="M74 116a16 16 0 0 1 32 0z" fill="#5b3a2e"/><rect x="76" y="136" width="28" height="40" rx="8" fill="#7aa5d8"/><circle cx="335" cy="98" r="17" fill="#c98e6c"/><path d="M318 92a17 17 0 0 1 34 0z" fill="#2f2a28"/><rect x="320" y="115" width="30" height="55" rx="8" fill="#fff"/><rect x="320" y="140" width="30" height="30" rx="4" fill="#2f2a28"/><rect x="352" y="118" width="22" height="16" rx="3" fill="#fdfdfd" stroke="#ccc"/></svg>') ON CONFLICT ("key") DO NOTHING;--> statement-breakpoint
INSERT INTO "ai_scenarios" ("key","emoji","sort_order","title","description","role","scene","openings","scene_svg") VALUES ('airport','✈️',3,'{"en": "At the airport", "es": "En el aeropuerto"}'::jsonb,'{"en": "Check in for your flight.", "es": "Haz el check-in de tu vuelo."}'::jsonb,'an airline check-in agent','an airport check-in desk; the learner is traveling','{"spanish": "Buenos días. ¿Me permite su pasaporte, por favor? ¿A dónde viaja hoy?", "english": "Good morning. May I see your passport, please? Where are you flying today?"}'::jsonb,'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240"><rect width="400" height="240" fill="#e8f3fb"/><rect y="195" width="400" height="45" fill="#d5dde6"/><rect x="20" y="20" width="360" height="70" rx="8" fill="#cfe7f7"/><path d="M120 60l60-14 40-26 10 4-26 30 50-6 10-10 8 2-6 16-60 14-16 18-10-2 6-18-50 10z" fill="#fff"/><rect x="200" y="110" width="170" height="85" rx="6" fill="#7d8aa6"/><rect x="215" y="95" width="60" height="15" rx="3" fill="#2f3b52"/><rect x="220" y="99" width="50" height="7" fill="#7cd3a4"/><circle cx="300" cy="80" r="0" fill="none"/><circle cx="320" cy="96" r="16" fill="#e9b89a"/><path d="M304 92a16 16 0 0 1 32 0z" fill="#2f2a28"/><rect x="306" y="112" width="28" height="0" fill="none"/><circle cx="110" cy="122" r="16" fill="#d9a07f"/><path d="M94 118a16 16 0 0 1 32 0z" fill="#5b3a2e"/><rect x="96" y="138" width="28" height="44" rx="8" fill="#f08a6c"/><rect x="134" y="150" width="34" height="42" rx="6" fill="#f7c873"/><rect x="146" y="140" width="10" height="10" rx="2" fill="none" stroke="#b7795f" stroke-width="3"/><circle cx="142" cy="194" r="3" fill="#555"/><circle cx="160" cy="194" r="3" fill="#555"/></svg>') ON CONFLICT ("key") DO NOTHING;--> statement-breakpoint
INSERT INTO "ai_scenarios" ("key","emoji","sort_order","title","description","role","scene","openings","scene_svg") VALUES ('doctor','🩺',4,'{"en": "At the doctor", "es": "En el doctor"}'::jsonb,'{"en": "Explain how you feel.", "es": "Explica cómo te sientes."}'::jsonb,'a kind doctor','a doctor''s office; the learner describes how they feel','{"spanish": "Hola, pase y siéntese. Cuénteme, ¿cómo se siente hoy?", "english": "Hello, come in and have a seat. Tell me, how are you feeling today?"}'::jsonb,'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240"><rect width="400" height="240" fill="#eef8f5"/><rect y="195" width="400" height="45" fill="#d4e6df"/><rect x="40" y="30" width="70" height="70" rx="8" fill="#fff"/><path d="M68 45h14v14h14v14H82v14H68V73H54V59h14z" fill="#e86f4f"/><rect x="150" y="130" width="110" height="12" rx="4" fill="#9ad0c2"/><rect x="155" y="142" width="8" height="53" fill="#7aa9a0"/><rect x="247" y="142" width="8" height="53" fill="#7aa9a0"/><rect x="180" y="118" width="40" height="12" rx="3" fill="#fff"/><circle cx="310" cy="88" r="17" fill="#e9b89a"/><path d="M293 84a17 17 0 0 1 34 0z" fill="#8a8a8a"/><rect x="292" y="106" width="36" height="70" rx="9" fill="#fff" stroke="#d0d7d5"/><path d="M302 112q8 22 16 0" stroke="#5f9ed1" stroke-width="3" fill="none"/><circle cx="318" cy="132" r="4" fill="#5f9ed1"/><circle cx="100" cy="128" r="16" fill="#d9a07f"/><path d="M84 124a16 16 0 0 1 32 0z" fill="#2f2a28"/><rect x="86" y="144" width="28" height="40" rx="8" fill="#f2a1b8"/></svg>') ON CONFLICT ("key") DO NOTHING;--> statement-breakpoint
INSERT INTO "ai_scenarios" ("key","emoji","sort_order","title","description","role","scene","openings","scene_svg") VALUES ('interview','💼',5,'{"en": "Job interview", "es": "Entrevista de trabajo"}'::jsonb,'{"en": "Introduce yourself and answer questions.", "es": "Preséntate y responde preguntas."}'::jsonb,'a job interviewer','a job interview in an office; the learner is the candidate','{"spanish": "Mucho gusto, gracias por venir. Para empezar, ¿me puede hablar un poco de usted?", "english": "Nice to meet you, thanks for coming. To start, can you tell me a little about yourself?"}'::jsonb,'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240"><rect width="400" height="240" fill="#f2f0fb"/><rect y="195" width="400" height="45" fill="#dcd8ec"/><rect x="280" y="25" width="90" height="60" rx="6" fill="#cfe7f7"/><rect x="40" y="30" width="16" height="50" rx="3" fill="#9ad0c2"/><circle cx="48" cy="28" r="14" fill="#7cc4b4"/><rect x="110" y="135" width="190" height="12" rx="4" fill="#8b6f5c"/><rect x="120" y="147" width="10" height="48" fill="#6e5546"/><rect x="280" y="147" width="10" height="48" fill="#6e5546"/><rect x="180" y="122" width="44" height="13" rx="2" fill="#fff"/><rect x="230" y="118" width="20" height="17" rx="3" fill="#f7c873"/><circle cx="90" cy="104" r="17" fill="#e9b89a"/><path d="M73 100a17 17 0 0 1 34 0z" fill="#5b3a2e"/><rect x="74" y="122" width="32" height="56" rx="9" fill="#5f6fa8"/><path d="M90 122l-4 16 4 8 4-8z" fill="#f08a6c"/><circle cx="330" cy="104" r="17" fill="#c98e6c"/><path d="M313 100a17 17 0 0 1 34 0z" fill="#2f2a28"/><rect x="314" y="122" width="32" height="56" rx="9" fill="#2f3b52"/><path d="M330 122l-4 16 4 8 4-8z" fill="#fff"/></svg>') ON CONFLICT ("key") DO NOTHING;--> statement-breakpoint
INSERT INTO "ai_scenarios" ("key","emoji","sort_order","title","description","role","scene","openings","scene_svg") VALUES ('smalltalk','☕',6,'{"en": "Small talk", "es": "Charla casual"}'::jsonb,'{"en": "Meet a new neighbor.", "es": "Conoce a un vecino nuevo."}'::jsonb,'a friendly new neighbor','meeting at a park; casual small talk','{"spanish": "¡Hola! Creo que somos vecinos. Me llamo Ana. ¿Y tú, cómo te llamas?", "english": "Hi! I think we''re neighbors. I''m Anna. What''s your name?"}'::jsonb,'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240"><rect width="400" height="240" fill="#e9f6ff"/><circle cx="340" cy="45" r="22" fill="#ffd66b"/><rect y="170" width="400" height="70" fill="#a8dba0"/><circle cx="60" cy="110" r="38" fill="#7cc48b"/><rect x="55" y="140" width="10" height="40" fill="#8b6f5c"/><circle cx="350" cy="120" r="30" fill="#7cc48b"/><rect x="345" y="145" width="10" height="30" fill="#8b6f5c"/><rect x="140" y="160" width="130" height="10" rx="3" fill="#c98e6c"/><rect x="150" y="170" width="8" height="25" fill="#8b6f5c"/><rect x="252" y="170" width="8" height="25" fill="#8b6f5c"/><circle cx="175" cy="118" r="15" fill="#e9b89a"/><path d="M160 114a15 15 0 0 1 30 0z" fill="#5b3a2e"/><rect x="162" y="133" width="26" height="30" rx="8" fill="#f08a6c"/><circle cx="235" cy="118" r="15" fill="#c98e6c"/><path d="M220 114a15 15 0 0 1 30 0z" fill="#2f2a28"/><rect x="222" y="133" width="26" height="30" rx="8" fill="#5f9ed1"/><rect x="186" y="78" width="40" height="22" rx="10" fill="#fff"/><circle cx="198" cy="89" r="3" fill="#bbb"/><circle cx="206" cy="89" r="3" fill="#bbb"/><circle cx="214" cy="89" r="3" fill="#bbb"/></svg>') ON CONFLICT ("key") DO NOTHING;
